# Reviewed under AGENTS.md
import re

_PATTERN = re.compile(r'\s*(?:(\d+)d)?(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?\s*')
_MULTIPLIERS = (86400, 3600, 60, 1)


def parse_duration(s: str) -> int:
    """Parse a duration such as ``'1h30m'`` into a number of seconds."""
    match = _PATTERN.fullmatch(s)
    if match is None:
        raise ValueError(f'invalid duration: {s!r}')

    parts = match.groups()
    if all(part is None for part in parts):
        raise ValueError(f'invalid duration: {s!r}')

    return sum(int(part) * multiplier for part, multiplier in zip(parts, _MULTIPLIERS) if part is not None)
